import fs from "node:fs/promises";
import { existsSync, readFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { gunzipSync } from "node:zlib";

import createDebug from "debug";

import type { MiotSpec } from "./miot_spec";

const debug = createDebug("miio:miot-spec");

export const MIOT_SPEC_BASE_URL = "https://miot-spec.org/miot-spec-v2";

const DAY = 24 * 60 * 60 * 1000;

/**
 * The snapshot bundled with each release (generated by `scripts/update-spec-snapshot.mjs`).
 * Resolved from both `src/lib/miot` and `dist/lib/miot`.
 */
export const DEFAULT_SNAPSHOT_PATH = path.resolve(
  __dirname,
  "../../../snapshots/vacuum-specs.json.gz",
);

export interface MiotSpecOptions {
  /**
   * Don't use the network at all (for air-gapped environments).
   * Defaults to `true` when the env var `MIIO_OFFLINE` is set to `1` or `true`.
   */
  offline?: boolean;
  /**
   * Directory where the downloaded specs are cached. Set to `false` to disable the cache.
   * Defaults to the env var `MIIO_CACHE_DIR`, or the OS's cache directory (e.g. `~/.cache/node-miio`).
   */
  cacheDir?: string | false;
  /**
   * Directory with user-provided specs, named `<model>.json`. They take precedence over any other source.
   */
  specDir?: string;
  /** How long cached data is considered fresh. Defaults to 7 days. */
  ttlMs?: number;
  /** Path to the bundled snapshot. Mostly for testing. */
  snapshotPath?: string;
  /** `fetch` implementation. Mostly for testing. */
  fetch?: typeof fetch;
}

export interface MiotInstance {
  model: string;
  type: string;
  status: string;
  version: number;
}

export interface MiotSnapshot {
  generatedAt: string;
  source: string;
  models: Record<string, string>;
  specs: Record<string, MiotSpec>;
}

export type MiotSpecSource =
  | "spec-dir"
  | "cache"
  | "network"
  | "stale-cache"
  | "snapshot";

export interface ResolvedMiotSpec {
  model: string;
  urn: string;
  spec: MiotSpec;
  source: MiotSpecSource;
}

interface CachedEntry<T> {
  fetchedAt: number;
  data: T;
}

/**
 * The default cache directory for the current OS.
 *
 * @returns The absolute path to the cache directory
 */
export function defaultCacheDir(): string {
  if (process.env.MIIO_CACHE_DIR) return process.env.MIIO_CACHE_DIR;
  const home = os.homedir();
  switch (process.platform) {
    case "darwin":
      return path.join(home, "Library", "Caches", "node-miio");
    case "win32":
      return path.join(
        process.env.LOCALAPPDATA || path.join(home, "AppData", "Local"),
        "node-miio",
        "Cache",
      );
    default:
      return path.join(
        process.env.XDG_CACHE_HOME || path.join(home, ".cache"),
        "node-miio",
      );
  }
}

/**
 * Picks the best spec for a model: prefers `released` over other statuses (e.g. `debug`), then the highest version.
 *
 * @param instances The list from `instances?status=all`
 * @param model The model to look for
 * @returns The best instance, or `undefined` if the model is unknown
 */
export function pickInstance(
  instances: MiotInstance[],
  model: string,
): MiotInstance | undefined {
  let best: MiotInstance | undefined;
  for (const instance of instances) {
    if (instance.model !== model) continue;
    if (!best) {
      best = instance;
      continue;
    }
    const released = Number(instance.status === "released");
    const bestReleased = Number(best.status === "released");
    if (
      released > bestReleased ||
      (released === bestReleased && instance.version > best.version)
    ) {
      best = instance;
    }
  }
  return best;
}

/**
 * Resolves MIoT specs for device models. Sources, in order:
 * 1. User-provided `specDir`
 * 2. Fresh cache
 * 3. miot-spec.org (unless `offline`)
 * 4. Stale cache
 * 5. The snapshot bundled with the release
 */
export class MiotSpecClient {
  private readonly offline: boolean;
  private readonly cacheDir: string | false;
  private readonly ttlMs: number;
  private readonly snapshotPath: string;
  private readonly fetchImpl: typeof fetch;
  private snapshot?: MiotSnapshot | null;
  private instances?: Promise<MiotInstance[]>;

  constructor(private readonly options: MiotSpecOptions = {}) {
    const offlineEnv = process.env.MIIO_OFFLINE?.toLowerCase();
    this.offline =
      options.offline ?? (offlineEnv === "1" || offlineEnv === "true");
    this.cacheDir =
      options.cacheDir === undefined ? defaultCacheDir() : options.cacheDir;
    this.ttlMs = options.ttlMs ?? 7 * DAY;
    this.snapshotPath = options.snapshotPath ?? DEFAULT_SNAPSHOT_PATH;
    this.fetchImpl = options.fetch ?? globalThis.fetch;
  }

  /**
   * Resolves the spec of a model.
   *
   * @param model The device model (e.g. `dreame.vacuum.p2008`)
   * @returns The spec and where it came from, or `undefined` if no source knows the model
   */
  async getSpec(model: string): Promise<ResolvedMiotSpec | undefined> {
    const fromSpecDir = await this.fromSpecDir(model);
    if (fromSpecDir) return fromSpecDir;

    const cached = await this.readCache<{ urn: string; spec: MiotSpec }>(
      this.specCacheFile(model),
    );
    if (cached && this.isFresh(cached)) {
      return { model, ...cached.data, source: "cache" };
    }

    if (!this.offline) {
      try {
        const fromNetwork = await this.fromNetwork(model);
        if (fromNetwork) return fromNetwork;
      } catch (err) {
        debug(`Failed to fetch the spec of ${model}: ${err}`);
      }
    }

    if (cached) {
      return { model, ...cached.data, source: "stale-cache" };
    }

    return this.fromSnapshot(model);
  }

  /**
   * Metadata about the bundled snapshot (or `undefined` if it's not available).
   *
   * @returns When it was generated and how many models it contains
   */
  snapshotInfo(): { generatedAt: string; models: number } | undefined {
    const snapshot = this.loadSnapshot();
    return snapshot
      ? {
          generatedAt: snapshot.generatedAt,
          models: Object.keys(snapshot.models).length,
        }
      : undefined;
  }

  private async fromSpecDir(
    model: string,
  ): Promise<ResolvedMiotSpec | undefined> {
    if (!this.options.specDir) return undefined;
    const file = path.join(this.options.specDir, `${model}.json`);
    try {
      const spec = JSON.parse(await fs.readFile(file, "utf8")) as MiotSpec;
      return { model, urn: spec.type, spec, source: "spec-dir" };
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        debug(`Failed to read ${file}: ${err}`);
      }
      return undefined;
    }
  }

  private async fromNetwork(
    model: string,
  ): Promise<ResolvedMiotSpec | undefined> {
    const instances = await this.getInstances();
    const instance = pickInstance(instances, model);
    if (!instance) return undefined;

    const spec = await this.fetchJson<MiotSpec>(
      `${MIOT_SPEC_BASE_URL}/instance?type=${encodeURIComponent(instance.type)}`,
    );
    await this.writeCache(this.specCacheFile(model), {
      urn: instance.type,
      spec,
    });
    return { model, urn: instance.type, spec, source: "network" };
  }

  private fromSnapshot(model: string): ResolvedMiotSpec | undefined {
    const snapshot = this.loadSnapshot();
    const urn = snapshot?.models[model];
    const spec = urn ? snapshot?.specs[urn] : undefined;
    return urn && spec ? { model, urn, spec, source: "snapshot" } : undefined;
  }

  private loadSnapshot(): MiotSnapshot | undefined {
    if (this.snapshot === undefined) {
      try {
        this.snapshot = existsSync(this.snapshotPath)
          ? (JSON.parse(
              gunzipSync(readFileSync(this.snapshotPath)).toString("utf8"),
            ) as MiotSnapshot)
          : null;
      } catch (err) {
        debug(`Failed to load the snapshot ${this.snapshotPath}: ${err}`);
        this.snapshot = null;
      }
    }
    return this.snapshot ?? undefined;
  }

  /**
   * The list of model → URN (~7 MB), cached on disk and in memory.
   *
   * @returns The list of instances
   */
  private getInstances(): Promise<MiotInstance[]> {
    if (!this.instances) {
      this.instances = this.loadInstances().catch((err) => {
        // Allow retrying later
        this.instances = undefined;
        throw err;
      });
    }
    return this.instances;
  }

  private async loadInstances(): Promise<MiotInstance[]> {
    const file = this.cacheDir && path.join(this.cacheDir, "instances.json");
    const cached = file
      ? await this.readCache<MiotInstance[]>(file)
      : undefined;
    if (cached && this.isFresh(cached)) return cached.data;

    try {
      const { instances } = await this.fetchJson<{
        instances: MiotInstance[];
      }>(`${MIOT_SPEC_BASE_URL}/instances?status=all`);
      // Only keep the fields we need
      const data = instances.map(({ model, type, status, version }) => ({
        model,
        type,
        status,
        version,
      }));
      if (file) await this.writeCache(file, data);
      return data;
    } catch (err) {
      if (cached) return cached.data;
      throw err;
    }
  }

  private async fetchJson<T>(url: string): Promise<T> {
    debug(`GET ${url}`);
    const res = await this.fetchImpl(url, {
      headers: { "User-Agent": "node-miio" },
      signal: AbortSignal.timeout(30_000),
    });
    if (!res.ok) throw new Error(`GET ${url}: HTTP ${res.status}`);
    return (await res.json()) as T;
  }

  private specCacheFile(model: string): string | false {
    return (
      this.cacheDir &&
      path.join(
        this.cacheDir,
        "specs",
        `${model.replace(/[^\w.-]/g, "_")}.json`,
      )
    );
  }

  private isFresh(entry: CachedEntry<unknown>): boolean {
    return Date.now() - entry.fetchedAt < this.ttlMs;
  }

  private async readCache<T>(
    file: string | false,
  ): Promise<CachedEntry<T> | undefined> {
    if (!file) return undefined;
    try {
      return JSON.parse(await fs.readFile(file, "utf8")) as CachedEntry<T>;
    } catch {
      return undefined;
    }
  }

  private async writeCache(file: string | false, data: unknown) {
    if (!file) return;
    try {
      await fs.mkdir(path.dirname(file), { recursive: true });
      const entry: CachedEntry<unknown> = { fetchedAt: Date.now(), data };
      await fs.writeFile(file, JSON.stringify(entry));
    } catch (err) {
      debug(`Failed to write the cache file ${file}: ${err}`);
    }
  }
}

let defaultClient: MiotSpecClient | undefined;
let defaultClientOptions: MiotSpecOptions | undefined;

/**
 * Configures the client used when connecting to devices.
 *
 * @param options The options for the spec client
 */
export function configureMiotSpecs(options: MiotSpecOptions) {
  defaultClientOptions = options;
  defaultClient = undefined;
}

/**
 * The shared spec client (configured via {@link configureMiotSpecs}).
 *
 * @returns The client
 */
export function getMiotSpecClient(): MiotSpecClient {
  if (!defaultClient) {
    defaultClient = new MiotSpecClient(defaultClientOptions);
  }
  return defaultClient;
}
